func updateNoticeEligible(cmd *cobra.Command, format string) bool {
	if os.Getenv("SEMREL_UPDATE_CHECK") != "1" || os.Getenv("CI") != "" || format != "text" {
		return false
	}
	if !term.IsTerminal(int(os.Stdin.Fd())) || !term.IsTerminal(int(os.Stdout.Fd())) ||
		!term.IsTerminal(int(os.Stderr.Fd())) {
		return false
	}
	path := cmd.CommandPath()
	switch {
	case path == "semrel update", path == "semrel plugin update",
		strings.HasPrefix(path, "semrel completion"), path == "semrel internal-update-check":
		return false
	}
	return true
}

func updateNoticeCacheDir() (string, error) {
	dir, err := os.UserCacheDir()
	if err != nil {
		return "", fmt.Errorf("finding user cache directory: %w", err)
	}
	registryURL := strings.TrimSpace(os.Getenv(registry.EnvRegistryURL))
	if registryURL == "" {
		registryURL = registry.DefaultBaseURL
	}
	hash := sha256.Sum256([]byte(registryURL))
	return filepath.Join(dir, "semrel", "update-notices", fmt.Sprintf("%x", hash[:8])), nil
}

