func refreshUpdateCache(ctx context.Context, dir string) error {
	results := make(chan error, 2)
	go func() { results <- refreshReleaseCache(ctx, dir) }()
	go func() { results <- refreshPluginCache(ctx, dir) }()
	return errors.Join(<-results, <-results)
}

func refreshReleaseCache(ctx context.Context, dir string) error {
	release, err := fetchLatestRelease(ctx)
	if err != nil {
		return fmt.Errorf("checking semrel: %w", err)
	}
	parsed, err := semver.ParseVersion(release.TagName)
	if err != nil || release.TagName == "" || parsed.Prerelease != "" {
		return fmt.Errorf("checking semrel: latest release %q is not a stable semantic version", release.TagName)
	}
	return writeReleaseCache(dir, release)
}

func refreshPluginCache(ctx context.Context, dir string) (result error) {
	tempDir, err := os.MkdirTemp(dir, "registry-fetch-")
	if err != nil {
		return fmt.Errorf("creating registry cache: %w", err)
	}
	defer func() {
		if err := os.RemoveAll(tempDir); err != nil {
			result = errors.Join(result, fmt.Errorf("removing temporary registry cache: %w", err))
		}
	}()
	client, err := registry.NewRegistryClient(os.Getenv(registry.EnvRegistryURL), tempDir)
	if err == nil {
		var reg *registry.PluginRegistry
		reg, err = client.FetchMetadata(ctx)
		if err == nil {
			err = writePluginNoticeCache(dir, reg)
		}
	}
	if err != nil {
		return fmt.Errorf("checking plugins: %w", err)
	}
	return nil
}

