func writeNoticeCache(path string, value any) (result error) {
	data, err := json.Marshal(value)
	if err != nil {
		return fmt.Errorf("encoding update cache: %w", err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		return fmt.Errorf("creating update cache directory: %w", err)
	}
	file, err := os.CreateTemp(filepath.Dir(path), "update-*.tmp")
	if err != nil {
		return fmt.Errorf("creating update cache: %w", err)
	}
	defer func() {
		if err := os.Remove(file.Name()); err != nil && !errors.Is(err, os.ErrNotExist) {
			result = errors.Join(result, fmt.Errorf("removing temporary update cache: %w", err))
		}
	}()
	if _, err := file.Write(data); err != nil {
		_ = file.Close()
		return fmt.Errorf("writing update cache: %w", err)
	}
	if err := file.Close(); err != nil {
		return fmt.Errorf("closing update cache: %w", err)
	}
	if err := os.Rename(file.Name(), path); err != nil {
		return fmt.Errorf("replacing update cache: %w", err)
	}
	return nil
}

func newerStable(current, candidate string) bool {
	if strings.TrimSpace(current) == "" || strings.TrimSpace(candidate) == "" {
		return false
	}
	old, err := semver.ParseVersion(current)
	if err != nil {
		return false
	}
	next, err := semver.ParseVersion(candidate)
	return err == nil && next.Prerelease == "" && next.Compare(old) > 0
}

func showUpdateNotices(w io.Writer, dir, current string, now time.Time) error {
	releasePath := filepath.Join(dir, "release.json")
	if freshFile(releasePath, now, updateCacheMaxAge) {
		data, err := os.ReadFile(releasePath)
		if err != nil {
			return fmt.Errorf("reading release cache: %w", err)
		}
		var release githubRelease
		if err := json.Unmarshal(data, &release); err != nil {
			return fmt.Errorf("parsing release cache: %w", err)
		}
		if newerStable(current, release.TagName) {
			fmt.Fprintf(w, "Update available: semrel %s → %s. https://github.com/SemRels/semrel/releases/latest (check: `semrel update --check`)\n", current, release.TagName)
		}
	}
	registryPath := filepath.Join(dir, "registry-cache", "plugins.json")
	if !freshFile(registryPath, now, updateCacheMaxAge) {
		return nil
	}
	data, err := os.ReadFile(registryPath)
	if err != nil {
		return fmt.Errorf("reading plugin cache: %w", err)
	}
	var reg registry.PluginRegistry
	if err := json.Unmarshal(data, &reg); err != nil {
		return fmt.Errorf("parsing plugin cache: %w", err)
	}
	locked, err := ReadLockFile()
	if err != nil {
		return err
	}
	for _, entry := range locked.Plugins {
		meta, err := reg.FindPlugin(entry.Ref)
		if err != nil {
			fmt.Fprintf(w, "warning: update check: cannot look up %s: %v\n", entry.Ref, err)
			continue
		}
		if _, err := semver.ParseVersion(entry.Version); err != nil || strings.TrimSpace(entry.Version) == "" {
			fmt.Fprintf(w, "warning: update check: cannot compare version %q of %s\n", entry.Version, entry.Ref)
			continue
		}
		var latest string
		for _, candidate := range meta.Versions {
			if candidate.Prerelease || !newerStable(entry.Version, candidate.Version) {
				continue
			}
			if latest == "" || newerStable(latest, candidate.Version) {
				latest = candidate.Version
			}
		}
		if latest != "" {
			fmt.Fprintf(w, "Update available: %s %s → %s. Run `semrel plugin update --check`.\n", meta.CanonicalRef(), entry.Version, latest)
		}
	}
	return nil
}
